const X=[
{id:'LV-01',lvl:0,skill:b('Raoult; presión de burbuja','Raoult; burbuila-presioa'),title:b('Primer vapor de una mezcla','Nahaste baten lehen lurruna'),q:b('A una T fija, un líquido ideal tiene xA=0,400; P°A=600 mmHg y P°B=200 mmHg.','T finko batean, likido ideal batek xA=0,400 du; P°A=600 mmHg eta P°B=200 mmHg.'),parts:[{q:b('a) Presión de burbuja (mmHg)','a) Burbuila-presioa (mmHg)'),ans:360,abs:.1},{q:b('b) yA en el primer vapor','b) Lehen lurruneko yA'),ans:2/3,abs:.005}],hints:[b('P=xAP°A+(1−xA)P°B.','P=xAP°A+(1−xA)P°B.'),b('Calcula PA primero; luego yA=PA/P.','Lehenik PA kalkulatu; gero yA=PA/P.')],sol:[b('PA=0,400·600=240 mmHg y PB=0,600·200=120 mmHg.','PA=0,400·600=240 mmHg eta PB=0,600·200=120 mmHg.'),b('Pburbuja=240+120=<b>360 mmHg</b>.','Pburbuilea=240+120=<b>360 mmHg</b>.'),b('yA=240/360=<b>0,667</b>.','yA=240/360=<b>0,667</b>.')],res:b('360 mmHg; yA=0,667.','360 mmHg; yA=0,667.'),check:b('yA>xA porque A tiene P° mayor; yA+yB=1.','yA>xA da A-ren P° handiagoa delako; yA+yB=1.'),errs:b('Promediar las presiones sin ponderar o usar xA como vapor.','Presioak haztatu gabe batezbestekotzea edo xA lurrun gisa erabiltzea.')},
{id:'LV-02',lvl:0,skill:b('Henry y unidades','Henry eta unitateak'),title:b('Oxígeno disuelto en equilibrio','Orekan disolbatutako oxigenoa'),q:b('A temperatura constante, el convenio de Henry del curso da KH=1,50×10⁻³ mol·L⁻¹·atm⁻¹ para O₂. Sobre el líquido hay aire con PO₂=0,210 atm.','Tenperatura konstantean, ikastaroko Henry hitzarmenak O₂-rentzat KH=1,50×10⁻³ mol·L⁻¹·atm⁻¹ ematen du. Likidoaren gaineko airean PO₂=0,210 atm da.'),parts:[{q:b('a) Concentración disuelta de O₂ (mol/L)','a) Disolbatutako O₂ kontzentrazioa (mol/L)'),ans:.000315,abs:1e-7}],hints:[b('Usa la presión parcial del oxígeno, no la presión total del aire.','Erabili oxigenoaren presio partziala, ez airearen presio osoa.'),b('C=KH·PO₂.','C=KH·PO₂.')],sol:[b('Henry: C=1,50×10⁻³·0,210=<b>3,15×10⁻⁴ mol/L</b>.','Henry: C=1,50×10⁻³·0,210=<b>3,15×10⁻⁴ mol/L</b>.'),b('Unidades: (mol·L⁻¹·atm⁻¹)·atm=mol/L.','Unitateak: (mol·L⁻¹·atm⁻¹)·atm=mol/L.')],res:'3,15×10⁻⁴ mol/L',check:b('Si PO₂ se duplicara a T constante, la concentración también se duplicaría dentro del modelo diluido.','T konstantean PO₂ bikoiztuko balitz, kontzentrazioa ere bikoiztuko litzateke eredu diluituan.'),errs:b('Usar la presión total o una constante de Henry definida con la convención inversa.','Presio osoa erabiltzea edo alderantzizko hitzarmeneko Henry konstantea erabiltzea.')},
{id:'LV-03',lvl:1,skill:b('Porcentaje en masa y rocío','Masa-ehunekoa eta ihintza'),title:b('Primera gota de un vapor binario','Lurrun bitar baten lehen tanta'),q:b('Un vapor tiene 40,0 % en masa de benceno y 60,0 % de tolueno. M=78 y 92 g/mol; a la T de trabajo P°Bz=753 y P°Tol=290 mmHg.','Lurrunak bentzenoaren %40,0 eta toluenoaren %60,0 ditu masan. M=78 eta 92 g/mol; laneko T-an P°Bz=753 eta P°Tol=290 mmHg.'),parts:[{q:b('a) Fracción molar yBz','a) yBz frakzio molarra'),ans:.4401914,abs:.002},{q:b('b) Presión de rocío (mmHg)','b) Ihintz-presioa (mmHg)'),ans:397.6209,abs:.2},{q:b('c) xBz de la primera gota','c) Lehen tantako xBz'),ans:.2324427,abs:.002}],hints:[b('Base 100 g: convierte las dos masas a moles y normaliza.','100 g oinarria: bi masak moletara bihurtu eta normalizatu.'),b('P=1/(yBz/P°Bz+yTol/P°Tol).','P=1/(yBz/P°Bz+yTol/P°Tol).')],sol:[b('nBz=40/78=0,5128; nTol=60/92=0,6522 mol. yBz=0,5128/(0,5128+0,6522)=<b>0,4402</b>.','nBz=40/78=0,5128; nTol=60/92=0,6522 mol. yBz=0,5128/(0,5128+0,6522)=<b>0,4402</b>.'),b('Procío=1/(0,4402/753+0,5598/290)=<b>397,6 mmHg</b>.','Pihintza=1/(0,4402/753+0,5598/290)=<b>397,6 mmHg</b>.'),b('xBz=yBzP/P°Bz=0,4402·397,6/753=<b>0,2324</b>.','xBz=yBzP/P°Bz=0,4402·397,6/753=<b>0,2324</b>.')],res:b('yBz=0,4402; Procío=397,6 mmHg; xBz=0,2324.','yBz=0,4402; Pihintza=397,6 mmHg; xBz=0,2324.'),check:b('La gota menos volátil tiene menor fracción de benceno que el vapor; xBz+yTol=1.','Lurrunkortasun txikiagoko tantak lurrunak baino bentzeno-frakzio txikiagoa du; xBz+yTol=1.'),errs:b('Usar 40 % masa directamente como yBz, o calcular el rocío con la suma de Raoult.','Masa-% 40 zuzenean yBz gisa erabiltzea edo ihintza Raoult-en baturarekin kalkulatzea.')},
{id:'LV-04',lvl:1,skill:b('Rocío y lectura de presión','Ihintza eta presioaren irakurketa'),title:b('Un estado fuera de la envolvente','Inguratzailetik kanpoko egoera'),q:b('A 300 K, P°A=103,1 mmHg y P°B=32,06 mmHg. Una mezcla de vapor tiene yA=0,600.','300 K-an, P°A=103,1 mmHg eta P°B=32,06 mmHg. Lurrun-nahaste batek yA=0,600 du.'),parts:[{q:b('a) Presión de rocío (mmHg)','a) Ihintz-presioa (mmHg)'),ans:54.6562,abs:.05},{q:b('b) A 110 mmHg, ¿hay equilibrio L–V? Escribe 1 si sí, 0 si todo es líquido.','b) 110 mmHg-an, L–V orekarik ba al dago? Idatzi 1 baietz bada, 0 dena likidoa bada.'),ans:0,abs:.01}],hints:[b('Calcula Procío con y.','Kalkulatu Pihintza y-rekin.'),b('Compara 110 mmHg con las dos presiones de vapor puras.','Alderatu 110 mmHg bi lurrun-presio puruekin.')],sol:[b('Procío=1/(0,600/103,1+0,400/32,06)=<b>54,66 mmHg</b>.','Pihintza=1/(0,600/103,1+0,400/32,06)=<b>54,66 mmHg</b>.'),b('La burbuja nunca supera la P° máxima, 103,1 mmHg. Como 110>103,1, el estado es líquido para cualquier composición; no hay dos fases.','Burbuila-presioa ez da inoiz P° handiena baino handiagoa, 103,1 mmHg. 110>103,1 denez, egoera likidoa da edozein konposiziotan; ez dago bi faserik.')],res:b('Procío=54,66 mmHg; a 110 mmHg, todo líquido.','Pihintza=54,66 mmHg; 110 mmHg-an dena likidoa.'),check:b('Una presión superior a ambas P° está por encima de toda la envolvente de equilibrio.','Bi P°ak baino presio handiagoa oreka-inguratzaile osoaren gainetik dago.'),errs:b('Extrapolar una curva de rocío a una presión que no admite vapor en equilibrio.','Orekan lurrunik onartzen ez duen presiora ihintz-kurba estrapolatzea.')},
{id:'LV-05',lvl:1,skill:b('Fases de Gibbs y Raoult','Gibbs-en faseak eta Raoult'),title:b('Contar grados de libertad y hallar burbuja','Askatasun-graduak zenbatu eta burbuila kalkulatu'),q:b('Una mezcla binaria tiene dos fases L+V en equilibrio. A una T fija, xA=0,250, P°A=500 mmHg y P°B=200 mmHg.','Nahaste bitarrak L+V bi fase ditu orekan. T finko batean, xA=0,250, P°A=500 mmHg eta P°B=200 mmHg.'),parts:[{q:b('a) AG de la mezcla L+V','a) L+V nahastearen AG'),ans:2,abs:.01},{q:b('b) Presión de burbuja (mmHg)','b) Burbuila-presioa (mmHg)'),ans:275,abs:.1}],hints:[b('Para Gibbs usa K=2 y F=2.','Gibbs-erako erabili K=2 eta F=2.'),b('Pburbuja=xAPA°+(1−xA)PB°.','Pburbuilea=xAPA°+(1−xA)PB°.')],sol:[b('AG=K−F+2=2−2+2=<b>2</b>. Con T ya fijada, queda un grado composicional más otro de presión en la descripción completa.','AG=K−F+2=2−2+2=<b>2</b>. T finkatuta dagoenez, konposiziozko gradu bat eta presiozko beste bat geratzen dira deskribapen osoan.'),b('P=0,250·500+0,750·200=125+150=<b>275 mmHg</b>.','P=0,250·500+0,750·200=125+150=<b>275 mmHg</b>.')],res:'AG=2; Pburbuja=275 mmHg.',check:b('A presiones parciales: 125+150=275 mmHg.','Presio partzialetan: 125+150=275 mmHg.'),errs:b('Contar K como el número de sustancias en vez del de componentes independientes, o usar y en Raoult.','K substantzia-kopurutzat hartzea osagai independenteen ordez, edo Raoult-en y erabiltzea.' )},
{id:'LV-06',lvl:2,skill:b('Pxy y regla de la palanca','Pxy eta palankaren legea'),title:b('Separación de una mezcla a 80 °C','Nahaste baten bereizketa 80 °C-an'),q:b('Mezcla ideal benceno–tolueno a 80 °C: P°Bz=753, P°Tol=290 mmHg. Estado global zBz=0,400 y P=400 mmHg.','Bentzeno–tolueno nahaste ideala 80 °C-an: P°Bz=753, P°Tol=290 mmHg. Egoera globala zBz=0,400 eta P=400 mmHg.'),parts:[{q:b('a) xBz líquido','a) Likidoaren xBz'),ans:.237581,abs:.002},{q:b('b) yBz vapor','b) Lurrunaren yBz'),ans:.447246,abs:.002},{q:b('c) V/F','c) V/F'),ans:.774659,abs:.003}],hints:[b('Comprueba antes si Procío(z)<P<Pburbuja(z).','Lehenik egiaztatu Pihintza(z)<P<Pburbuila(z) den.'),b('x=(P−PB°)/(PA°−PB°); y=(1/P−1/PB°)/(1/PA°−1/PB°).','x=(P−PB°)/(PA°−PB°); y=(1/P−1/PB°)/(1/PA°−1/PB°).')],sol:[b('Pburbuja(z)=475,2 mmHg y Procío(z)=384,6 mmHg, así que 400 mmHg cae en L+V.','Pburbuilea(z)=475,2 mmHg eta Pihintza(z)=384,6 mmHg; beraz, 400 mmHg L+V eremuan dago.'),b('xBz=(400−290)/(753−290)=<b>0,2376</b>; yBz=(1/400−1/290)/(1/753−1/290)=<b>0,4472</b>.','xBz=(400−290)/(753−290)=<b>0,2376</b>; yBz=(1/400−1/290)/(1/753−1/290)=<b>0,4472</b>.'),b('V/F=(0,400−0,2376)/(0,4472−0,2376)=<b>0,775</b>. L/F=0,225.','V/F=(0,400−0,2376)/(0,4472−0,2376)=<b>0,775</b>. L/F=0,225.')],res:b('xBz=0,238; yBz=0,447; V/F=0,775.','xBz=0,238; yBz=0,447; V/F=0,775.'),check:b('x<z<y y las fases suman 0,225+0,775=1.','x<z<y eta faseek 0,225+0,775=1 ematen dute.'),errs:b('Aplicar la palanca si P está fuera de L+V, o asignar la fracción de vapor al brazo incorrecto.' ,'P L+V-tik kanpo dagoenean palanka aplikatzea edo lurrun-frakzioa beso okerrari esleitzea.'),rubric:b('Región y curvas 25 % · equilibrio x,y 40 % · palanca y balance 25 % · unidades y coherencia 10 %.','Eremua eta kurbak %25 · x,y oreka %40 · palanka eta balantzea %25 · unitateak eta koherentzia %10.')},
{id:'LV-07',lvl:2,skill:b('Txy y Antoine','Txy eta Antoine'),title:b('Equilibrio a 98 °C y 1 atm','Oreka 98 °C-an eta 1 atm-an'),q:b('Benceno–tolueno ideal a P=760 mmHg. Usa log₁₀P(mmHg)=A−B/(C+T[°C]): Bz (A=6,90565; B=1211,033; C=220,79), Tol (A=6,95464; B=1344,8; C=219,48). A T=98 °C, zBz=0,400.','Bentzeno–tolueno ideala P=760 mmHg-an. Erabili log₁₀P(mmHg)=A−B/(C+T[°C]): Bz (A=6,90565; B=1211,033; C=220,79), Tol (A=6,95464; B=1344,8; C=219,48). T=98 °C-an, zBz=0,400.'),parts:[{q:b('a) xBz líquido','a) Likidoaren xBz'),ans:.313262,abs:.003},{q:b('b) yBz vapor','b) Lurrunaren yBz'),ans:.527110,abs:.003},{q:b('c) V/F','c) V/F'),ans:.405608,abs:.005}],hints:[b('Calcula P° de cada compuesto por Antoine a 98 °C.','Kalkulatu konposatu bakoitzaren P° Antoine-rekin 98 °C-an.'),b('Usa Pburbuja de x y P rocío de y para invertir las relaciones.','Erabili x-ren burbuila-P eta y-ren ihintza-P erlazioak alderantzikatzeko.')],sol:[b('Antoine: P°Bz=1278,8 y P°Tol=523,3 mmHg.','Antoine: P°Bz=1278,8 eta P°Tol=523,3 mmHg.'),b('xBz=(760−523,3)/(1278,8−523,3)=<b>0,3133</b>; yBz=(1/760−1/523,3)/(1/1278,8−1/523,3)=<b>0,5271</b>.','xBz=(760−523,3)/(1278,8−523,3)=<b>0,3133</b>; yBz=(1/760−1/523,3)/(1/1278,8−1/523,3)=<b>0,5271</b>.'),b('V/F=(0,400−0,3133)/(0,5271−0,3133)=<b>0,406</b>; L/F=0,594.','V/F=(0,400−0,3133)/(0,5271−0,3133)=<b>0,406</b>; L/F=0,594.')],res:b('xBz=0,313; yBz=0,527; V/F=0,406.','xBz=0,313; yBz=0,527; V/F=0,406.'),check:b('A T dada, P está entre burbuja y rocío para z=0,4; x<z<y.','T emanda, P burbuila- eta ihintza-presioen artean dago z=0,4-rentzat; x<z<y.'),errs:b('Usar una ecuación de Antoine en K con constantes de °C.','K-ko Antoine ekuazioa °C-ko konstanteekin erabiltzea.'),rubric:b('Antoine y unidades 30 % · composiciones de fase 40 % · palanca 20 % · interpretación 10 %.','Antoine eta unitateak %30 · fase-konposizioak %40 · palanka %20 · interpretazioa %10.')},
{id:'LV-08',lvl:2,skill:b('Flash: balances totales y de componente','Flash-a: balantze osoak eta osagai-balantzea'),title:b('Fracciones de las dos salidas','Bi irteeren frakzioak'),q:b('Una alimentación F=120 mol con zA=0,430 se separa en un flash ideal. El equilibrio da xA=0,250 en el líquido e yA=0,700 en el vapor.','F=120 mol eta zA=0,430 dituen elikadura flash ideal batean bereizten da. Orekak xA=0,250 ematen du likidoan eta yA=0,700 lurrunean.'),parts:[{q:b('a) L (mol)','a) L (mol)'),ans:72,abs:.1},{q:b('b) V (mol)','b) V (mol)'),ans:48,abs:.1}],hints:[b('Balance total F=L+V.','Balantze osoa F=L+V.'),b('Resuelve con V/F=(z−x)/(y−x).','Ebatzi V/F=(z−x)/(y−x) erabiliz.')],sol:[b('V/F=(0,430−0,250)/(0,700−0,250)=0,400 → V=<b>48 mol</b>.','V/F=(0,430−0,250)/(0,700−0,250)=0,400 → V=<b>48 mol</b>.'),b('L=F−V=120−48=<b>72 mol</b>.','L=F−V=120−48=<b>72 mol</b>.'),b('A: 0,25·72+0,70·48=18+33,6=51,6 mol=zF.','A: 0,25·72+0,70·48=18+33,6=51,6 mol=zF.')],res:'L=72 mol; V=48 mol.',check:b('L+V=120 y la salida A suma 51,6 mol, igual que la entrada.','L+V=120 eta A-ren irteerek 51,6 mol batzen dituzte, sarreraren berdin.'),errs:b('Restar z−x en vez de y−x en la palanca.','Palankan y−x erabili beharrean z−x kentzea.'),rubric:b('Balance y fracciones 30 % · palanca 30 % · caudales 20 % · cierre de A 20 %.','Balantzea eta frakzioak %30 · palanka %30 · emariak %20 · A-ren itxiera %20.')},
{id:'LV-09',lvl:3,skill:b('Flash, rendimiento de fases y conservación','Flash-a, fase-errendimendua eta kontserbazioa'),title:b('Diseño de un separador flash','Flash-bereizgailu baten diseinua'),q:b('Se alimentan F=100 mol con zA=0,450. A la T y P elegidas, el líquido de salida tiene xA=0,200 y el vapor yA=0,800.','F=100 mol eta zA=0,450 dituen elikadura sartzen da. Aukeratutako T eta P-an, irteerako likidoak xA=0,200 du eta lurrunak yA=0,800.'),parts:[{q:b('a) V/F','a) V/F'),ans:5/12,abs:.003},{q:b('b) Caudal de líquido L (mol)','b) Likido-emaria L (mol)'),ans:58.3333,abs:.1},{q:b('c) Moles de A en el vapor','c) A-ren molak lurrunean'),ans:33.3333,abs:.1}],hints:[b('La palanca da primero V/F.','Palankak lehenik V/F ematen du.'),b('Los balances son molares; luego multiplica yA por V.','Balantzeak molarrak dira; gero yA V-rekin biderkatu.')],sol:[b('V/F=(z−x)/(y−x)=(0,450−0,200)/(0,800−0,200)=<b>0,4167</b>.','V/F=(z−x)/(y−x)=(0,450−0,200)/(0,800−0,200)=<b>0,4167</b>.'),b('V=41,667 mol y L=100−V=<b>58,333 mol</b>.','V=41,667 mol eta L=100−V=<b>58,333 mol</b>.'),b('nA,vapor=yA·V=0,800·41,667=<b>33,333 mol</b>; nA,liq=0,200·58,333=11,667 mol; suman 45,000 mol.','nA,lurrun= yA·V=0,800·41,667=<b>33,333 mol</b>; nA,likido=0,200·58,333=11,667 mol; batura 45,000 mol da.')],res:b('V/F=0,4167; L=58,33 mol; A en vapor=33,33 mol.','V/F=0,4167; L=58,33 mol; A lurrunean=33,33 mol.'),check:b('El balance global A cierra: 11,667+33,333=45,000=zF.','A-ren balantze globala ixten da: 11,667+33,333=45,000=zF.'),errs:b('Tratar yA como la fracción de vapor; la fracción de fase es V/F.','yA lurrun-frakzio gisa hartzea; fase-frakzioa V/F da.'),rubric:b('Planteamiento de balances 25 % · palanca 25 % · caudales 25 % · comprobación de componente 25 %.','Balantzeen planteamendua %25 · palanka %25 · emariak %25 · osagaiaren egiaztapena %25.')},
{id:'LV-10',lvl:3,skill:b('Coligativas complementarias y disociación','Koligatibo osagarriak eta disoziazioa'),title:b('Separar aportes de electrolito y no electrolito','Elektrolitoaren eta ez-elektrolitoaren ekarpenak bereiztea'),q:b('Disolución diluida con 1,00 mol CaCl₂ en 5,00 kg de agua y 17,5 g de un no electrolito de masa molar 350 g/mol. Se mide ΔTf=0,830 K; Kf=1,86 K·kg/mol.','Disoluzio diluituak 1,00 mol CaCl₂ ditu 5,00 kg uretan, eta 17,5 g elektrolito ez den 350 g/mol-eko solutu bat. Neurtutako ΔTf=0,830 K da; Kf=1,86 K·kg/mol.'),parts:[{q:b('a) Molalidad del no electrolito (mol/kg)','a) Elektrolito ez denaren molalitatea (mol/kg)'),ans:.01,abs:.0001},{q:b('b) Grado de disociación α de CaCl₂','b) CaCl₂-ren α disoziazio-gradua'),ans:.590608,abs:.003}],hints:[b('n del no electrolito=17,5/350; divide entre 5,00 kg.','Elektrolito ez denaren n=17,5/350; zatitu 5,00 kg-rekin.'),b('ΔTf/Kf=mno+i·mCaCl₂; para CaCl₂, i=1+2α.','ΔTf/Kf=mno+i·mCaCl₂; CaCl₂-rentzat i=1+2α.')],sol:[b('mno=(17,5/350)/5,00=<b>0,0100 mol/kg</b>; mCaCl₂=1,00/5,00=0,200 mol/kg.','mno=(17,5/350)/5,00=<b>0,0100 mol/kg</b>; mCaCl₂=1,00/5,00=0,200 mol/kg.'),b('ΔTf/Kf=0,830/1,86=0,44624=mno+0,200(1+2α). Despejando, α=<b>0,591</b>.','ΔTf/Kf=0,830/1,86=0,44624=mno+0,200(1+2α). Askatu eta α=<b>0,591</b> lortzen da.'),b('Esta es una ampliación sobre propiedades coligativas; no es una prioridad principal del curso actual.','Hau propietate koligatiboen zabalkuntza da; ez da ikastaroaren egungo lehentasun nagusia.')],res:b('mno=0,0100 mol/kg; α=0,591.','mno=0,0100 mol/kg; α=0,591.'),check:b('0<α<1; si CaCl₂ se disociara por completo, aportaría 0,600 mol/kg de partículas, más que los 0,436 calculados.','0<α<1; CaCl₂ erabat disoziatuz gero m-partikulen ekarpena 0,600 mol/kg litzateke, kalkulatutako 0,436 baino handiagoa.'),errs:b('Omitir la contribución coligativa del soluto no electrolito o tomar ν=2 para CaCl₂.','Elektrolito ez den solutuaren ekarpen koligatiboa baztertzea edo CaCl₂-rentzat ν=2 hartzea.'),rubric:b('Molalidades 25 % · suma de partículas 30 % · i correcto 20 % · α y rango físico 25 %.','Molalitateak %25 · partikulen batura %30 · i zuzena %20 · α eta tarte fisikoa %25.')}
 ];

